package com.example.starter.observation;

import org.springframework.http.HttpStatus;

import java.util.List;

/**
 * 业务异常：携带 HTTP 状态及可选的冲突详情（冲突字段、当前版本），由全局异常处理器转为错误响应。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;
    private final List<String> conflictFields;
    private final Integer currentVersion;

    private ApiException(HttpStatus status, String message, List<String> conflictFields, Integer currentVersion) {
        super(message);
        this.status = status;
        this.conflictFields = conflictFields;
        this.currentVersion = currentVersion;
    }

    public HttpStatus status() {
        return status;
    }

    public List<String> conflictFields() {
        return conflictFields;
    }

    public Integer currentVersion() {
        return currentVersion;
    }

    /**
     * 400：请求参数不合法（如读数格式错误）。
     */
    public static ApiException badRequest(String message) {
        return new ApiException(HttpStatus.BAD_REQUEST, message, null, null);
    }

    /**
     * 404：观测记录或基线版本不存在。
     */
    public static ApiException notFound(String message) {
        return new ApiException(HttpStatus.NOT_FOUND, message, null, null);
    }

    /**
     * 409：通用冲突（记录已存在、删除版本不匹配、requestId 异参复用）。
     */
    public static ApiException conflict(String message, Integer currentVersion) {
        return new ApiException(HttpStatus.CONFLICT, message, null, currentVersion);
    }

    /**
     * 409：三方合并字段冲突，携带冲突字段与当前版本，不写入任何部分结果。
     */
    public static ApiException mergeConflict(List<String> conflictFields, int currentVersion) {
        return new ApiException(HttpStatus.CONFLICT,
                "merge conflict on fields: " + String.join(", ", conflictFields),
                List.copyOf(conflictFields), currentVersion);
    }

    /**
     * 410：记录已删除，拒绝新的修改和删除。
     */
    public static ApiException gone(String message) {
        return new ApiException(HttpStatus.GONE, message, null, null);
    }
}
package com.example.starter.observation;

import com.fasterxml.jackson.annotation.JsonInclude;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.time.Instant;
import java.util.List;
import java.util.Map;

/**
 * 冲突解决响应：返回不可变解决记录要点及解决后指向版本的内容。
 *
 * @param resolutionId    全局唯一解决记录标识
 * @param observationId   观测记录唯一标识
 * @param requestId       生成该记录的请求标识
 * @param baseVersion     基线版本号
 * @param previousVersion 解决前当前版本号
 * @param version         解决后指向的版本号（无变化解决时等于 previousVersion）
 * @param contentChanged  解决后内容是否发生变化：false 表示未生成新观测版本
 * @param conflictFields  服务端重算出的冲突字段名列表
 * @param selections      各冲突字段的人工选择
 * @param operator        操作者标识
 * @param resolvedAtUtc   解决完成时刻（UTC，ISO-8601）
 * @param location        解决后版本的观测地点
 * @param reading         解决后版本的观测读数
 * @param note            解决后版本的观测备注
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record ResolutionResponse(
        String resolutionId,
        String observationId,
        String requestId,
        int baseVersion,
        int previousVersion,
        int version,
        boolean contentChanged,
        List<String> conflictFields,
        Map<String, String> selections,
        String operator,
        Instant resolvedAtUtc,
        String location,
        String reading,
        String note) {

    private static final TypeReference<Map<String, String>> SELECTIONS_TYPE = new TypeReference<>() {
    };

    /**
     * 由解决记录与指向版本的快照构造响应；选择映射从记录中的 JSON 原文反序列化。
     */
    public static ResolutionResponse of(ResolutionRecord record, ObservationSnapshot pointed,
                                        ObjectMapper objectMapper) {
        return new ResolutionResponse(
                record.resolutionId(),
                record.observationId(),
                record.requestId(),
                record.baseVersion(),
                record.previousVersion(),
                record.newVersion(),
                record.contentChanged(),
                List.copyOf(record.conflictFields()),
                parseSelections(record.fieldSelections(), objectMapper),
                record.operator(),
                record.resolvedAtUtc(),
                pointed.location(),
                pointed.reading(),
                pointed.note());
    }

    private static Map<String, String> parseSelections(String json, ObjectMapper objectMapper) {
        try {
            return objectMapper.readValue(json, SELECTIONS_TYPE);
        } catch (JsonProcessingException e) {
            throw new IllegalStateException("failed to deserialize stored selections", e);
        }
    }
}
package com.example.starter.observation;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.sql.Timestamp;
import java.time.Instant;
import java.util.List;
import java.util.Optional;

/**
 * 冲突解决记录持久化：conflict_resolution 记录成功解决的完整上下文，不可变、永不更新。
 * 所有 SQL 使用参数化查询；冲突字段列表与选择映射以 JSON 原文存储。
 */
@Repository
public class ResolutionRepository {

    private static final TypeReference<List<String>> FIELD_LIST_TYPE = new TypeReference<>() {
    };
    private static final TypeReference<java.util.Map<String, String>> SELECTIONS_TYPE = new TypeReference<>() {
    };

    private final JdbcTemplate jdbcTemplate;
    private final ObjectMapper objectMapper;

    public ResolutionRepository(JdbcTemplate jdbcTemplate, ObjectMapper objectMapper) {
        this.jdbcTemplate = jdbcTemplate;
        this.objectMapper = objectMapper;
    }

    /**
     * 插入一条不可变解决记录；resolutionId 主键或 (observationId, requestId) 唯一键冲突时抛出重复键异常。
     */
    public void insert(ResolutionRecord record) {
        jdbcTemplate.update(
                "INSERT INTO conflict_resolution (resolution_id, observation_id, request_id, "
                        + "base_version, previous_version, new_version, candidate_location, candidate_reading, "
                        + "candidate_note, conflict_fields, field_selections, operator, content_changed, "
                        + "resolved_at_utc, created_at) "
                        + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)",
                record.resolutionId(),
                record.observationId(),
                record.requestId(),
                record.baseVersion(),
                record.previousVersion(),
                record.newVersion(),
                record.candidateLocation(),
                record.candidateReading(),
                record.candidateNote(),
                writeJson(record.conflictFields()),
                record.fieldSelections(),
                record.operator(),
                record.contentChanged(),
                Timestamp.from(record.resolvedAtUtc()));
    }

    /**
     * 按全局唯一 resolutionId 查询解决记录；不存在时返回空。
     */
    public Optional<ResolutionRecord> findByResolutionId(String resolutionId) {
        return jdbcTemplate.query(
                        "SELECT resolution_id, observation_id, request_id, base_version, previous_version, "
                                + "new_version, candidate_location, candidate_reading, candidate_note, "
                                + "conflict_fields, field_selections, operator, content_changed, resolved_at_utc "
                                + "FROM conflict_resolution WHERE resolution_id = ?",
                        RESOLUTION_MAPPER, resolutionId)
                .stream().findFirst();
    }

    /**
     * 按 observationId 按解决时刻先后查询全部解决记录。
     */
    public List<ResolutionRecord> findByObservationId(String observationId) {
        return jdbcTemplate.query(
                "SELECT resolution_id, observation_id, request_id, base_version, previous_version, "
                        + "new_version, candidate_location, candidate_reading, candidate_note, "
                        + "conflict_fields, field_selections, operator, content_changed, resolved_at_utc "
                        + "FROM conflict_resolution WHERE observation_id = ? "
                        + "ORDER BY resolved_at_utc ASC, resolution_id ASC",
                RESOLUTION_MAPPER, observationId);
    }

    private String writeJson(Object value) {
        try {
            return objectMapper.writeValueAsString(value);
        } catch (JsonProcessingException e) {
            throw new IllegalStateException("failed to serialize resolution fields", e);
        }
    }

    private List<String> readFieldList(String json) {
        try {
            return objectMapper.readValue(json, FIELD_LIST_TYPE);
        } catch (JsonProcessingException e) {
            throw new IllegalStateException("failed to deserialize conflict fields", e);
        }
    }

    /**
     * 反序列化存储的选择 JSON；仅用于持久化层内部校验与比较，不参与记录不可变语义。
     */
    public java.util.Map<String, String> readSelections(String json) {
        try {
            return objectMapper.readValue(json, SELECTIONS_TYPE);
        } catch (JsonProcessingException e) {
            throw new IllegalStateException("failed to deserialize field selections", e);
        }
    }

    private final RowMapper<ResolutionRecord> RESOLUTION_MAPPER = (rs, rowNum) -> new ResolutionRecord(
            rs.getString("resolution_id"),
            rs.getString("observation_id"),
            rs.getString("request_id"),
            rs.getInt("base_version"),
            rs.getInt("previous_version"),
            rs.getInt("new_version"),
            rs.getString("candidate_location"),
            rs.getString("candidate_reading"),
            rs.getString("candidate_note"),
            readFieldList(rs.getString("conflict_fields")),
            rs.getString("field_selections"),
            rs.getString("operator"),
            rs.getTimestamp("resolved_at_utc").toInstant(),
            rs.getBoolean("content_changed"));
}
package com.example.starter.observation;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.util.Optional;

/**
 * 幂等去重持久化：request_log 仅记录成功结果，与业务变更同事务原子提交；失败回滚不占键。
 */
@Repository
public class RequestLogRepository {

    private static final RowMapper<RequestLogEntry> ENTRY_MAPPER = (rs, rowNum) -> new RequestLogEntry(
            rs.getString("request_id"),
            rs.getString("fingerprint"),
            rs.getString("operation"),
            (Integer) rs.getObject("response_status"),
            rs.getString("response_body"));

    private final JdbcTemplate jdbcTemplate;

    public RequestLogRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    /**
     * 按请求标识查询去重记录；不存在时返回空。
     */
    public Optional<RequestLogEntry> find(String requestId) {
        return jdbcTemplate.query(
                        "SELECT request_id, fingerprint, operation, response_status, response_body "
                                + "FROM request_log WHERE request_id = ?",
                        ENTRY_MAPPER, requestId)
                .stream().findFirst();
    }

    /**
     * 在写事务内先占位插入去重记录（响应暂为空），主键冲突时由数据库串行化并发同键请求。
     * 业务失败时随事务回滚，不占用该键。
     */
    public void insertPlaceholder(String requestId, String fingerprint, String operation) {
        jdbcTemplate.update(
                "INSERT INTO request_log (request_id, fingerprint, operation, response_status, response_body, created_at) "
                        + "VALUES (?, ?, ?, NULL, NULL, CURRENT_TIMESTAMP)",
                requestId, fingerprint, operation);
    }

    /**
     * 业务成功后回填响应，与业务变更在同一事务内提交。
     */
    public void complete(String requestId, int responseStatus, String responseBody) {
        jdbcTemplate.update(
                "UPDATE request_log SET response_status = ?, response_body = ? WHERE request_id = ?",
                responseStatus, responseBody, requestId);
    }
}
package com.example.starter.observation;

/**
 * 幂等去重记录：对应 request_log 表的一行，仅成功请求会落库。
 *
 * @param requestId      全局唯一请求标识
