        merge("req-rh-1", "obs-18", 1, "站点B", "1.0", "备注").andExpect(status().isOk());
        // 第一次解决：站点B/C 冲突选 CANDIDATE，备注自动合并为离线备注 → v3
        resolve("req-rh-2", "res-18a", "obs-18", 1, 2,
