                .andExpect(status().isOk())
                .andExpect(jsonPath("$.version").value(5));

        // 历史按解决时刻先后返回；每条记录不可变，始终指向解决时的版本
        mockMvc.perform(get("/api/observations/{id}/resolutions", "obs-18"))
                .andExpect(status().isOk())
