                .andExpect(jsonPath("$[0].note").value("离线备注"))
                .andExpect(jsonPath("$[0].operator").value("op1"))
                .andExpect(jsonPath("$[1].resolutionId").value("res-18b"))
                .andExpect(jsonPath("$[1].version").value(5))
